import math

# Set alpha to the Golden Ratio, the assumed simplifying class of irrational alpha
alpha = (1 + math.sqrt(5)) / 2

def calculate_LHS(m, n, alpha):
    # Calculate fractional parts
    fm = (m * alpha) - math.floor(m * alpha)
    fn = (n * alpha) - math.floor(n * alpha)

    # LHS = n * {m*alpha} - m * {n*alpha}
    lhs = n * fm - m * fn
    return lhs

def check_pretty(m, n, alpha, k):
    # Check the original simplified equation: m + m*floor(n*alpha) - n*floor(m*alpha) = k
    lhs_original = m + m * math.floor(n * alpha) - n * math.floor(m * alpha)
    return abs(lhs_original - k) < 1e-9

